-- Seed data. Safe to re-run: uses ON CONFLICT DO NOTHING.
--
-- IMPORTANT — READ BEFORE RUNNING:
-- The password_hash values below are PLACEHOLDERS ('*** RUN scripts/hash-password.js ***') and
-- will NOT let anyone log in. This is deliberate: a real bcrypt hash can only be generated by
-- actually running bcrypt, which needs `npm install` first (not available in the sandbox this
-- file was written in). After `npm install` in backend/, run:
--   node scripts/hash-password.js "YourChosenPassword"
-- and paste the printed hash in place of each placeholder below before running this seed file.
-- Change every seeded password immediately after first login in production.

BEGIN;

ON CONFLICT (email) DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT (sku) DO NOTHING;

-- Opening stock ledger entries for every seeded product
SELECT id, 'Opening Stock', stock_qty, 0, stock_qty, 'OPEN-0001' FROM products
WHERE NOT EXISTS (SELECT 1 FROM stock_movements WHERE reference = 'OPEN-0001' AND product_id = products.id);

COMMIT;
